"""ALNS destroy and repair operators for the CVRP solver-design subject."""
from __future__ import annotations

import math

from .state import _Route, _demand, _distance_scale


def _random_removal(solution, q, rng):
    customers = _customers_in_solution(solution)
    if not customers:
        return []
    q = min(max(1, q), len(customers))
    removed = rng.sample(customers, q)
    for customer in removed:
        _remove_customer(solution, customer)
    return removed


def _worst_removal(solution, q, rng, p=3.0):
    removed = []
    q = max(0, min(q, len(_customers_in_solution(solution))))
    while len(removed) < q:
        candidates = []
        for route in solution.routes:
            for pos, customer in enumerate(route.customers):
                saving = -route.cost_of_remove(pos)
                candidates.append((saving, customer))
        if not candidates:
            break
        candidates.sort(reverse=True)
        idx = min(len(candidates) - 1, int(math.floor((rng.random() ** p) * len(candidates))))
        customer = candidates[idx][1]
        if _remove_customer(solution, customer):
            removed.append(customer)
    return removed


def _shaw_removal(solution, q, rng, p=6.0, phi_dist=9.0, phi_demand=3.0, phi_route=2.0):
    customers = _customers_in_solution(solution)
    if not customers:
        return []
    q = min(max(1, q), len(customers))
    max_distance = _distance_scale(solution.instance)
    max_demand = max(float(max(_demand(solution.instance, c) for c in customers)), 1.0)
    original_route = {
        customer: idx
        for idx, route in enumerate(solution.routes)
        for customer in route.customers
    }
    seed = rng.choice(customers)
    removed = [seed]
    _remove_customer(solution, seed)
    while len(removed) < q:
        candidates = _customers_in_solution(solution)
        if not candidates:
            break
        related = []
        for customer in candidates:
            best = float("inf")
            for ref in removed:
                same_route = original_route.get(customer) == original_route.get(ref)
                score = (
                    phi_dist * (solution.instance.distance(customer, ref) / max_distance)
                    + phi_demand
                    * (abs(_demand(solution.instance, customer) - _demand(solution.instance, ref)) / max_demand)
                    + (0.0 if same_route else phi_route)
                )
                best = min(best, score)
            related.append((best, customer))
        related.sort(key=lambda item: item[0])
        idx = min(len(related) - 1, int(math.floor((rng.random() ** p) * len(related))))
        customer = related[idx][1]
        if _remove_customer(solution, customer):
            removed.append(customer)
    return removed


def _route_removal(solution, q, rng):
    route_indexes = [idx for idx, route in enumerate(solution.routes) if route.customers]
    if not route_indexes:
        return []
    q = min(max(1, q), len(_customers_in_solution(solution)))
    rng.shuffle(route_indexes)
    removed = []
    for route_idx in route_indexes:
        if route_idx >= len(solution.routes):
            continue
        route = solution.routes[route_idx]
        if not route.customers:
            continue
        removed.extend(route.customers)
        route.customers = []
        route.recalculate()
        if len(removed) >= q:
            break
    solution.remove_empty_routes()
    return removed


def _greedy_insertion(solution, removed, rng, max_routes=None, context=None, reserve=0.0):
    pending = list(removed)
    rng.shuffle(pending)
    while pending:
        _check_repair_budget(context, reserve)
        best_idx = -1
        best_move = None
        for idx, customer in enumerate(pending):
            move = _best_repair_move(
                solution, customer, max_routes, context, reserve
            )
            if move is None:
                continue
            if best_move is None or move[0] < best_move[0]:
                best_idx = idx
                best_move = move
        if best_move is None:
            customer = pending.pop()
            if not _can_open_new_route(solution, max_routes):
                raise ValueError("repair could not insert customer within route limit")
            _insert_new_route(solution, customer)
            continue
        customer = pending.pop(best_idx)
        _commit_repair_move(solution, customer, best_move)


def _regret2_insertion(solution, removed, rng, max_routes=None, context=None, reserve=0.0):
    _regret_insertion(solution, removed, rng, 2, max_routes, context, reserve)


def _regret3_insertion(solution, removed, rng, max_routes=None, context=None, reserve=0.0):
    _regret_insertion(solution, removed, rng, 3, max_routes, context, reserve)


def _regret_insertion(solution, removed, rng, k, max_routes=None, context=None, reserve=0.0):
    pending = list(removed)
    rng.shuffle(pending)
    k = max(2, int(k))
    while pending:
        _check_repair_budget(context, reserve)
        best_idx = -1
        best_score = float("-inf")
        best_delta = float("inf")
        best_move = None
        for idx, customer in enumerate(pending):
            insertions = _best_insertions(solution, customer, context, reserve)
            if insertions:
                delta = insertions[0][0]
                considered = insertions[:k]
                score = sum(
                    move_delta - delta
                    for move_delta, _route_idx, _pos in considered[1:]
                )
                if len(considered) < k:
                    score += (k - len(considered)) * max(
                        0.0,
                        _new_route_cost(solution, customer) - delta,
                    )
                move = _direct_move(insertions[0])
            else:
                move = _best_ejection_insertion(
                    solution, customer, max_routes, context, reserve
                )
                if move is None:
                    score = float("inf")
                    delta = _new_route_cost(solution, customer)
                else:
                    # An ejection is only considered after all direct insertions
                    # fail, so retain the original regret priority for such a
                    # constrained customer.
                    score = float("inf")
                    delta = move[0]
            if score > best_score or (score == best_score and delta < best_delta):
                best_idx = idx
                best_score = score
                best_delta = delta
                best_move = move
        customer = pending.pop(best_idx)
        if best_move is None:
            if not _can_open_new_route(solution, max_routes):
                raise ValueError("repair could not insert customer within route limit")
            _insert_new_route(solution, customer)
        else:
            _commit_repair_move(solution, customer, best_move)


def _best_repair_move(solution, customer, max_routes, context, reserve):
    insertions = _best_insertions(solution, customer, context, reserve)
    if insertions:
        return _direct_move(insertions[0])
    return _best_ejection_insertion(solution, customer, max_routes, context, reserve)


def _direct_move(insertion):
    delta, route_idx, pos = insertion
    return (delta, "direct", route_idx, pos)


def _best_ejection_insertion(solution, customer, max_routes, context, reserve):
    """Find the lowest-cost capacity-feasible insert/eject/reinsert chain."""
    if max_routes is None or len(solution.routes) < max_routes:
        return None
    instance = solution.instance
    customer_demand = _demand(instance, customer)
    best_move = None
    for target_idx, target in enumerate(solution.routes):
        _check_repair_budget(context, reserve)
        for eject_pos, ejected in enumerate(target.customers):
            _check_repair_budget(context, reserve)
            remaining = target.customers[:eject_pos] + target.customers[eject_pos + 1 :]
            if target.load - _demand(instance, ejected) + customer_demand > instance.capacity:
                continue
            remove_delta = target.cost_of_remove(eject_pos)
            for customer_pos in range(len(remaining) + 1):
                _check_repair_budget(context, reserve)
                target_delta = remove_delta + _cost_of_insert_in_customers(
                    instance, remaining, customer, customer_pos
                )
                for receiver_idx, receiver in enumerate(solution.routes):
                    _check_repair_budget(context, reserve)
                    if receiver_idx == target_idx or not receiver.can_insert(ejected):
                        continue
                    for receiver_pos in range(len(receiver.customers) + 1):
                        _check_repair_budget(context, reserve)
                        combined_delta = target_delta + receiver.cost_of_insert(
                            ejected, receiver_pos
                        )
                        move = (
                            combined_delta,
                            "eject",
                            target_idx,
                            eject_pos,
                            customer_pos,
                            receiver_idx,
                            receiver_pos,
                        )
                        if best_move is None or move < best_move:
                            best_move = move
    return best_move


def _cost_of_insert_in_customers(instance, customers, customer, position):
    depot = instance.depot
    previous = depot if position == 0 else customers[position - 1]
    following = depot if position == len(customers) else customers[position]
    return (
        instance.distance(previous, customer)
        + instance.distance(customer, following)
        - instance.distance(previous, following)
    )


def _commit_repair_move(solution, customer, move):
    if move[1] == "direct":
        _delta, _kind, route_idx, pos = move
        _insert_existing(solution, customer, route_idx, pos)
        return
    _delta, _kind, target_idx, eject_pos, customer_pos, receiver_idx, receiver_pos = move
    target = solution.routes[target_idx]
    receiver = solution.routes[receiver_idx]
    ejected = target.remove(eject_pos)
    target.insert(customer, customer_pos)
    receiver.insert(ejected, receiver_pos)
    solution.rebuild_index()


def _best_insertions(solution, customer, context=None, reserve=0.0):
    insertions = []
    for route_idx, route in enumerate(solution.routes):
        _check_repair_budget(context, reserve)
        if not route.can_insert(customer):
            continue
        for pos in range(len(route.customers) + 1):
            _check_repair_budget(context, reserve)
            insertions.append((route.cost_of_insert(customer, pos), route_idx, pos))
    insertions.sort(key=lambda item: item[0])
    return insertions


def _check_repair_budget(context, reserve):
    if context is not None and context.remaining_time() <= reserve:
        raise ValueError("repair time limit reached")


def _can_open_new_route(solution, max_routes):
    return max_routes is None or len(solution.routes) < max_routes


def _insert_existing(solution, customer, route_idx, pos):
    solution.routes[route_idx].insert(customer, pos)
    solution.rebuild_index()


def _insert_new_route(solution, customer):
    route = _Route(solution.instance, [customer])
    if route.load > solution.instance.capacity:
        raise ValueError(f"customer {customer} demand exceeds capacity")
    solution.routes.append(route)
    solution.rebuild_index()


def _new_route_cost(solution, customer):
    depot = solution.instance.depot
    return solution.instance.distance(depot, customer) + solution.instance.distance(customer, depot)


def _customers_in_solution(solution):
    return [customer for route in solution.routes for customer in route.customers]


def _remove_customer(solution, customer):
    route_idx = solution.customer_route(customer)
    if route_idx < 0:
        return False
    pos = solution.customer_pos(customer)
    route = solution.routes[route_idx]
    route.remove(pos)
    solution.remove_empty_routes()
    return True

"""Local-search and VNS neighborhoods for the CVRP solver-design subject."""

from __future__ import annotations

from .config import _EPS
from .state import _demand, _prefix_loads, _route_distance


def _vns(solution, operators, max_no_improve, context, reserve):
    improved_overall = False
    operator_idx = 0
    no_improve_count = 0
    while (
        operator_idx < len(operators)
        and no_improve_count < max_no_improve
        and context.remaining_time() > reserve
    ):
        before = solution.total_cost
        if operators[operator_idx](solution, context, reserve):
            improved_overall = True
            delta = max(0.0, before - solution.total_cost)
            context.record_move(
                "vns",
                attempted=1,
                accepted=1,
                delta=delta,
                best_improved=delta > 0,
            )
            operator_idx = 0
            no_improve_count = 0
        else:
            context.record_move("vns", attempted=1, accepted=0)
            operator_idx += 1
            no_improve_count += 1
    return improved_overall


def _default_vns_operators():
    return [
        _two_opt_intra,
        _relocate,
        _or_opt_1,
        _or_opt_2,
        _or_opt_3,
        _swap,
        _two_for_one_exchange,
        _two_opt_star,
    ]


def _two_opt_intra(solution, context, reserve):
    improved = False
    for route in solution.routes:
        found = True
        while found and context.remaining_time() > reserve:
            found = False
            customers = route.customers
            for i in range(len(customers) - 1):
                for j in range(i + 1, len(customers)):
                    if context.remaining_time() <= reserve:
                        return improved
                    trial = (
                        customers[:i]
                        + list(reversed(customers[i : j + 1]))
                        + customers[j + 1 :]
                    )
                    delta = _route_distance(solution.instance, trial) - route.cost
                    if delta < -_EPS:
                        route.customers = trial
                        route.recalculate()
                        solution.rebuild_index()
                        improved = True
                        found = True
                        break
                if found:
                    break
    return improved


def _two_opt_intra_polish(solution, context, reserve, phase):
    accepted_moves = 0
    delta_sum = 0.0
    for route in solution.routes:
        found = True
        while found and context.remaining_time() > reserve:
            found = False
            customers = route.customers
            for i in range(len(customers) - 1):
                if context.remaining_time() <= reserve:
                    break
                for j in range(i + 1, len(customers)):
                    if context.remaining_time() <= reserve:
                        if accepted_moves <= 0:
                            context.record_move(phase, attempted=1, accepted=0)
                        return accepted_moves, delta_sum
                    trial = customers[:i] + list(reversed(customers[i : j + 1]))
                    trial += customers[j + 1 :]
                    delta = route.cost - _route_distance(solution.instance, trial)
                    if delta > _EPS:
                        route.customers = trial
                        route.recalculate()
                        solution.rebuild_index()
                        context.record_iteration(phase, 1)
                        context.record_move(
                            phase,
                            attempted=1,
                            accepted=1,
                            delta=delta,
                            best_improved=True,
                        )
                        found = True
                        accepted_moves += 1
                        delta_sum += float(delta)
                        break
                if found:
                    break
    if accepted_moves <= 0:
        context.record_move(phase, attempted=1, accepted=0)
    return accepted_moves, delta_sum


def _relocate(solution, context, reserve):
    improved = False
    found = True
    while found and context.remaining_time() > reserve:
        found = False
        routes = solution.routes
        for src_idx, src in enumerate(routes):
            for pos, customer in enumerate(list(src.customers)):
                best_gain = _EPS
                best_dst = -1
                best_pos = -1
                for dst_idx, dst in enumerate(routes):
                    if dst_idx == src_idx:
                        continue
                    if not dst.can_insert(customer):
                        continue
                    save = -src.cost_of_remove(pos)
                    for insert_pos in range(len(dst.customers) + 1):
                        if context.remaining_time() <= reserve:
                            return improved
                        gain = save - dst.cost_of_insert(customer, insert_pos)
                        if gain > best_gain:
                            best_gain = gain
                            best_dst = dst_idx
                            best_pos = insert_pos
                if best_dst >= 0:
                    src.remove(pos)
                    routes[best_dst].insert(customer, best_pos)
                    solution.rebuild_index()
                    improved = True
                    found = True
                    break
            if found:
                break
    return improved


def _swap(solution, context, reserve):
    improved = False
    found = True
    while found and context.remaining_time() > reserve:
        found = False
        routes = solution.routes
        for left_idx in range(len(routes) - 1):
            left = routes[left_idx]
            for right_idx in range(left_idx + 1, len(routes)):
                right = routes[right_idx]
                for li, left_customer in enumerate(left.customers):
                    for ri, right_customer in enumerate(right.customers):
                        if context.remaining_time() <= reserve:
                            return improved
                        left_load = (
                            left.load
                            - _demand(solution.instance, left_customer)
                            + _demand(solution.instance, right_customer)
                        )
                        right_load = (
                            right.load
                            - _demand(solution.instance, right_customer)
                            + _demand(solution.instance, left_customer)
                        )
                        if (
                            left_load > solution.instance.capacity
                            or right_load > solution.instance.capacity
                        ):
                            continue
                        trial_left = list(left.customers)
                        trial_right = list(right.customers)
                        trial_left[li] = right_customer
                        trial_right[ri] = left_customer
                        delta = (
                            _route_distance(solution.instance, trial_left)
                            + _route_distance(solution.instance, trial_right)
                            - left.cost
                            - right.cost
                        )
                        if delta < -_EPS:
                            left.customers = trial_left
                            right.customers = trial_right
                            left.recalculate()
                            right.recalculate()
                            solution.rebuild_index()
                            improved = True
                            found = True
                            break
                    if found:
                        break
                if found:
                    break
            if found:
                break
    return improved


def _two_for_one_exchange(solution, context, reserve):
    """First-improvement exchange of an adjacent pair for one other-route customer."""
    improved = False
    found = True
    capacity = solution.instance.capacity
    while found and context.remaining_time() > reserve:
        found = False
        routes = solution.routes
        for src_idx, src in enumerate(routes):
            if len(src.customers) < 2:
                continue
            for src_pos in range(len(src.customers) - 1):
                segment = src.customers[src_pos : src_pos + 2]
                segment_load = sum(_demand(solution.instance, customer) for customer in segment)
                src_without_segment = (
                    src.customers[:src_pos] + src.customers[src_pos + 2 :]
                )
                for dst_idx, dst in enumerate(routes):
                    if dst_idx == src_idx:
                        continue
                    for dst_pos, customer in enumerate(dst.customers):
                        if context.remaining_time() <= reserve:
                            return improved
                        customer_load = _demand(solution.instance, customer)
                        if (
                            src.load - segment_load + customer_load > capacity
                            or dst.load - customer_load + segment_load > capacity
                        ):
                            continue
                        trial_src = (
                            src_without_segment[:src_pos]
                            + [customer]
                            + src_without_segment[src_pos:]
                        )
                        for reverse in (False, True):
                            if context.remaining_time() <= reserve:
                                return improved
                            moved = list(reversed(segment)) if reverse else list(segment)
                            trial_dst = (
                                dst.customers[:dst_pos]
                                + moved
                                + dst.customers[dst_pos + 1 :]
                            )
                            delta = (
                                _route_distance(solution.instance, trial_src)
                                + _route_distance(solution.instance, trial_dst)
                                - src.cost
                                - dst.cost
                            )
                            if delta < -_EPS:
                                src.customers = trial_src
                                dst.customers = trial_dst
                                src.recalculate()
                                dst.recalculate()
                                solution.rebuild_index()
                                improved = True
                                found = True
                                break
                        if found:
                            break
                    if found:
                        break
                if found:
                    break
            if found:
                break
    return improved


def _or_opt_1(solution, context, reserve):
    return _or_opt(solution, 1, context, reserve)


def _or_opt_2(solution, context, reserve):
    return _or_opt(solution, 2, context, reserve)


def _or_opt_3(solution, context, reserve):
    return _or_opt(solution, 3, context, reserve)


def _or_opt(solution, seg_len, context, reserve):
    improved = False
    found = True
    while found and context.remaining_time() > reserve:
        found = False
        routes = solution.routes
        for src_idx, src in enumerate(routes):
            if len(src.customers) < seg_len:
                continue
            for pos in range(len(src.customers) - seg_len + 1):
                segment = src.customers[pos : pos + seg_len]
                segment_demand = sum(_demand(solution.instance, c) for c in segment)
                src_without = src.customers[:pos] + src.customers[pos + seg_len :]
                old_src = src.cost
                new_src = (
                    _route_distance(solution.instance, src_without)
                    if src_without
                    else 0.0
                )
                best_gain = _EPS
                best_dst = -1
                best_pos = -1
                best_rev = False
                for dst_idx, dst in enumerate(routes):
                    if dst_idx == src_idx:
                        continue
                    if dst.load + segment_demand > solution.instance.capacity:
                        continue
                    for insert_pos in range(len(dst.customers) + 1):
                        for reverse in ([False, True] if seg_len > 1 else [False]):
                            if context.remaining_time() <= reserve:
                                return improved
                            moved = (
                                list(reversed(segment)) if reverse else list(segment)
                            )
                            trial_dst = (
                                dst.customers[:insert_pos]
                                + moved
                                + dst.customers[insert_pos:]
                            )
                            gain = (
                                old_src
                                + dst.cost
                                - new_src
                                - _route_distance(solution.instance, trial_dst)
                            )
                            if gain > best_gain:
                                best_gain = gain
                                best_dst = dst_idx
                                best_pos = insert_pos
                                best_rev = reverse
                if best_dst >= 0:
                    moved = list(reversed(segment)) if best_rev else list(segment)
                    src.customers = src_without
                    dst = routes[best_dst]
                    dst.customers = (
                        dst.customers[:best_pos] + moved + dst.customers[best_pos:]
                    )
                    src.recalculate()
                    dst.recalculate()
                    solution.remove_empty_routes()
                    improved = True
                    found = True
                    break
            if found:
                break
    return improved


def _two_opt_star(solution, context, reserve):
    improved = False
    found = True
    while found and context.remaining_time() > reserve:
        found = False
        routes = solution.routes
        for left_idx in range(len(routes) - 1):
            left = routes[left_idx]
            for right_idx in range(left_idx + 1, len(routes)):
                right = routes[right_idx]
                prefix_left = _prefix_loads(solution.instance, left.customers)
                prefix_right = _prefix_loads(solution.instance, right.customers)
                for left_pos in range(len(left.customers) + 1):
                    for right_pos in range(len(right.customers) + 1):
                        if context.remaining_time() <= reserve:
                            return improved
                        new_left = (
                            left.customers[:left_pos] + right.customers[right_pos:]
                        )
                        new_right = (
                            right.customers[:right_pos] + left.customers[left_pos:]
                        )
                        if (
                            prefix_left[left_pos]
                            + (prefix_right[-1] - prefix_right[right_pos])
                            > solution.instance.capacity
                        ):
                            continue
                        if (
                            prefix_right[right_pos]
                            + (prefix_left[-1] - prefix_left[left_pos])
                            > solution.instance.capacity
                        ):
                            continue
                        delta = (
                            _route_distance(solution.instance, new_left)
                            + _route_distance(solution.instance, new_right)
                            - left.cost
                            - right.cost
                        )
                        if delta < -_EPS:
                            left.customers = new_left
                            right.customers = new_right
                            left.recalculate()
                            right.recalculate()
                            solution.remove_empty_routes()
                            improved = True
                            found = True
                            break
                    if found:
                        break
                if found:
                    break
            if found:
                break
    return improved
